-- Saída web 2026: preserva congelamento 64 e comparativos; altera somente 11 atividades da plataforma.
WITH anterior AS(SELECT result->'rows'->0->'payload' AS payload FROM estudo.notebook_runs WHERE id=64 AND frozen AND status='ok' AND NOT truncated),
m AS (SELECT 'outros_esportes' AS serie,r->>'categoria' AS categoria,jsonb_build_object('valor',(r->>'percentual')::numeric,'contagem',(r->>'total')::bigint,'denominador',(r->>'denominador')::bigint) AS atual FROM estudo.notebook_runs n CROSS JOIN LATERAL jsonb_array_elements(n.result->'rows') r WHERE n.id=71 AND n.frozen AND n.status='ok' AND NOT n.truncated AND (r->>'ano')::integer=2026 ),
notas AS(SELECT 'outros_esportes' AS serie,'Atividades importadas por activity_date de 01/01 a 26/09/2026, tipo preenchido; exclui indicação aspect_type=delete do Strava. Base: 308.420 atividades de todos os tipos, inclusive Run; 5.398 exclusões entre 313.818 registros, sem tipos nulos. Não conta usuários nem conclusões de provas. Os 11 tipos apresentados não somam 100%. Mapeamento exato registrado na consulta 284 rev1; Trilha=Hike. Fonte 280 rev1/65, comparação congelada 71, coleta própria de 30/09/2026. Ano parcial; não comparar quantidades com 2025 inteiro como crescimento anual.' AS nota),
comps AS(SELECT c.value||CASE WHEN m.serie IS NOT NULL THEN jsonb_build_object('atual',m.atual,'status','calculado') ELSE '{}'::jsonb END AS item,c.ordinality AS ordem FROM anterior CROSS JOIN LATERAL jsonb_array_elements(payload->'comparacoes') WITH ORDINALITY c LEFT JOIN m ON m.serie=c.value->>'serie' AND m.categoria=c.value->>'categoria')
SELECT payload||jsonb_build_object('meta',payload->'meta'||jsonb_build_object('origem',(payload->'meta'->>'origem')||'; atividades da plataforma: fontes 65 e 71, coleta própria 30/09/2026; exclui indicação delete. Demais números preservados'),'comparacoes',(SELECT jsonb_agg(item ORDER BY ordem) FROM comps),
'conciliacao',(SELECT jsonb_object_agg(status,total) FROM(SELECT item->>'status' AS status,count(*) AS total FROM comps GROUP BY 1) q),'series',(SELECT jsonb_agg(s.value||CASE WHEN n.nota IS NOT NULL THEN jsonb_build_object('ressalva',n.nota) ELSE '{}'::jsonb END ORDER BY s.ordinality) FROM jsonb_array_elements(payload->'series') WITH ORDINALITY s LEFT JOIN notas n ON n.serie=s.value->>'id')) AS payload
FROM anterior WHERE(SELECT count(*) FROM m)=11 AND(SELECT count(*) FROM comps WHERE item->>'status'='calculado' AND item->>'serie' IN(SELECT serie FROM m))=11
